        TLevel,
        (DistinctItem<TItem1, TLevel>, DistinctItem<TItem2, TLevel>)
    > SelectDistinct<TItem1, TItem2, TLevel>(Func<T1, T2, T3, T4, T5, T6, T7, T8, (IExpr<TItem1, TLevel>, IExpr<TItem2, TLevel>)> projection)
